macro_rules! Join {
    () => {
        # [doc = " Wait for all futures to complete."] # [doc = ""] # [doc = " Awaits multiple futures simultaneously, returning the output of the futures"] # [doc = " in the same container type they were created once all complete."] pub trait Join { # [doc = " The resulting output type."] type Output ; # [doc = " The [`Future`] implementation returned by this method."] type Future : Future < Output = Self :: Output > ; # [doc = " Waits for multiple futures to complete."] # [doc = ""] # [doc = " Awaits multiple futures simultaneously, returning the output of the futures"] # [doc = " in the same container type they we're created once all complete."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Awaiting multiple futures of the same type can be done using either a vector"] # [doc = " or an array."] # [doc = " ```rust"] # [doc = " #  futures::executor::block_on(async {"] # [doc = " use futures_concurrency::prelude::*;"] # [doc = ""] # [doc = " // all futures passed here are of the same type"] # [doc = " let fut1 = core::future::ready(1);"] # [doc = " let fut2 = core::future::ready(2);"] # [doc = " let fut3 = core::future::ready(3);"] # [doc = ""] # [doc = " let outputs = [fut1, fut2, fut3].join().await;"] # [doc = " assert_eq!(outputs, [1, 2, 3]);"] # [doc = " # })"] # [doc = " ```"] # [doc = ""] # [doc = " In practice however, it's common to want to await multiple futures of"] # [doc = " different types. For example if you have two different `async {}` blocks,"] # [doc = " you want to `.await`. To do that, you can call `.join` on tuples of futures."] # [doc = " ```rust"] # [doc = " #  futures::executor::block_on(async {"] # [doc = " use futures_concurrency::prelude::*;"] # [doc = ""] # [doc = " async fn some_async_fn() -> usize { 3 }"] # [doc = ""] # [doc = " // the futures passed here are of different types"] # [doc = " let fut1 = core::future::ready(1);"] # [doc = " let fut2 = async { 2 };"] # [doc = " let fut3 = some_async_fn();"] # [doc = " //                       ^ NOTE: no `.await` here!"] # [doc = ""] # [doc = " let outputs = (fut1, fut2, fut3).join().await;"] # [doc = " assert_eq!(outputs, (1, 2, 3));"] # [doc = " # })"] # [doc = " ```"] # [doc = ""] # [doc = " <br><br>"] # [doc = " This function returns a new future which polls all futures concurrently."] fn join (self) -> Self :: Future ; }
    };
}

Join!();